113	// ReadSession reads a session from Codex's storage (JSONL rollout file).
114	func (c *CodexAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
115		if input.SessionRef == "" {
116			return nil, errors.New("session reference (transcript path) is required")
117		}
118	
119		data, err := os.ReadFile(input.SessionRef)
120		if err != nil {
121			return nil, fmt.Errorf("failed to read transcript: %w", err)
122		}
123	
124		startTime, err := parseSessionStartTime(data)
125		if err != nil {
126			return nil, fmt.Errorf("failed to parse session start time: %w", err)
127		}
128	
129		// Extract modified files from the rollout transcript (best-effort, deduplicated).
130		var modifiedFiles []string
131		seen := make(map[string]struct{})
132		for _, lineData := range splitJSONL(data) {
133			for _, f := range extractFilesFromLine(lineData) {
134				if _, exists := seen[f]; !exists {
135					seen[f] = struct{}{}
136					modifiedFiles = append(modifiedFiles, f)
137				}
138			}
139		}
140	
141		return &agent.AgentSession{
142			SessionID:     input.SessionID,
143			AgentName:     c.Name(),
144			SessionRef:    input.SessionRef,
145			StartTime:     startTime,
146			NativeData:    data,
147			ModifiedFiles: modifiedFiles,
148		}, nil
149	}
