151	// WriteSession writes a session to Codex's storage (JSONL rollout file).
152	func (c *CodexAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
153		if session == nil {
154			return errors.New("session is nil")
155		}
156	
157		if session.AgentName != "" && session.AgentName != c.Name() {
158			return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, c.Name())
159		}
160	
161		if session.SessionRef == "" {
162			return errors.New("session reference (transcript path) is required")
163		}
164	
165		if len(session.NativeData) == 0 {
166			return errors.New("session has no native data to write")
167		}
168	
169		if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
170			return fmt.Errorf("failed to write transcript: %w", err)
171		}
172	
173		return nil
174	}
